using Lending.Domain.Platform;
using Lending.Infrastructure.Persistence;
using Microsoft.Extensions.Logging;

namespace Lending.Infrastructure.Platform;

/// <summary>
/// Persists notifications generated by real platform events. Preferences are read from the
/// platform settings row so disabling an event really stops new notifications.
/// </summary>
public sealed class PlatformNotificationService
{
    private readonly LendingDbContext _dbContext;
    private readonly PlatformSettingsStore _settingsStore;
    private readonly Application.Abstractions.IClock _clock;
    private readonly ILogger<PlatformNotificationService> _logger;

    public PlatformNotificationService(
        LendingDbContext dbContext,
        PlatformSettingsStore settingsStore,
        Application.Abstractions.IClock clock,
        ILogger<PlatformNotificationService> logger)
    {
        _dbContext = dbContext;
        _settingsStore = settingsStore;
        _clock = clock;
        _logger = logger;
    }

    public Task NotifyTenantCreatedAsync(
        Guid tenantId,
        string tenantName,
        CancellationToken cancellationToken) =>
        CreateForOrganizationEventAsync(
            setting => setting.NotifyTenantCreated,
            "Organización creada",
            $"Se creó la organización {tenantName}.",
            PlatformNotification.SeverityInfo,
            tenantId,
            cancellationToken);

    public Task NotifyTenantSuspendedAsync(
        Guid tenantId,
        string tenantName,
        CancellationToken cancellationToken) =>
        CreateForOrganizationEventAsync(
            setting => setting.NotifyTenantSuspended,
            "Organización suspendida",
            $"Se suspendió la organización {tenantName}.",
            PlatformNotification.SeverityWarning,
            tenantId,
            cancellationToken);

    public Task NotifyTenantReactivatedAsync(
        Guid tenantId,
        string tenantName,
        CancellationToken cancellationToken) =>
        CreateForOrganizationEventAsync(
            setting => setting.NotifyTenantReactivated,
            "Organización reactivada",
            $"Se reactivó la organización {tenantName}.",
            PlatformNotification.SeverityInfo,
            tenantId,
            cancellationToken);

    public async Task NotifySuspiciousAccessAsync(
        string email,
        string detail,
        CancellationToken cancellationToken)
    {
        var settings = await _settingsStore.GetAsync(cancellationToken);
        if (!settings.NotifySuspiciousAccess)
        {
            return;
        }

        await AddAsync(
            "Acceso sospechoso detectado",
            $"La cuenta {email} requiere revisión: {detail}",
            PlatformNotification.CategorySecurity,
            PlatformNotification.SeverityCritical,
            linkUrl: null,
            cancellationToken);
    }

    public async Task NotifyEmailFailureAsync(
        string error,
        CancellationToken cancellationToken)
    {
        try
        {
            var settings = await _settingsStore.GetAsync(cancellationToken);
            if (!settings.NotifyEmailFailures)
            {
                return;
            }

            await AddAsync(
                "Error al enviar correo",
                $"El envío de correo falló: {error}",
                PlatformNotification.CategoryEmail,
                PlatformNotification.SeverityWarning,
                linkUrl: "/admin/settings",
                cancellationToken);
        }
        catch (Exception exception)
        {
            _logger.LogWarning(
                exception,
                "Could not record the email failure notification.");
        }
    }

    private async Task CreateForOrganizationEventAsync(
        Func<PlatformSettings, bool> isEnabled,
        string title,
        string message,
        string severity,
        Guid tenantId,
        CancellationToken cancellationToken)
    {
        var settings = await _settingsStore.GetAsync(cancellationToken);
        if (!isEnabled(settings))
        {
            return;
        }

        await AddAsync(
            title,
            message,
            PlatformNotification.CategoryOrganization,
            severity,
            $"/admin/organizations/{tenantId}",
            cancellationToken);
    }

    private async Task AddAsync(
        string title,
        string message,
        string category,
        string severity,
        string? linkUrl,
        CancellationToken cancellationToken)
    {
        var notification = PlatformNotification.Create(
            title,
            message,
            category,
            severity,
            _clock.UtcNow,
            linkUrl);

        _dbContext.PlatformNotifications.Add(notification);
        await _dbContext.SaveChangesAsync(cancellationToken);
    }
}
